  icosaLR:  { base: 2, arrows: '↖↗', lattice: 'sphere', cells: true, twin: 'icosaGrid', ant: 'antIcosa', sphere: 'icosa', turns: [2, 1], round: true,
              rule: 'on an icosahedron of triangles: exit through the <b>0</b> left or <b>1</b> right edge' },
